@RestControllerAdvice
class ApiErrors {
  @ExceptionHandler(NotFoundException.class)
  ResponseEntity<?> handle(NotFoundException e) {
    return ResponseEntity.status(404).body(Map.of('error', e.getMessage()));
  }
}

// Go: คืน error ขึ้นไป พร้อม wrap context ด้วย %w
u, err := repo.FindByID(ctx, id)
if err != nil {
    return fmt.Errorf('find user %d: %w', id, err)
}

// ปลายทางตรวจชนิดด้วย errors.Is / errors.As
if errors.Is(err, ErrNotFound) {
    http.Error(w, 'not found', http.StatusNotFound)
    return
}

// Go: ยิงงานขนานพร้อมคุม error ด้วย errgroup
g, ctx := errgroup.WithContext(ctx)
for _, id := range ids {
    id := id
    g.Go(func() error {
        return fetchAndStore(ctx, id)
    })
}
if err := g.Wait(); err != nil { return err }

// Java 21+ : virtual threads ทำให้เขียน blocking แต่ scale ได้
try (var scope = Executors.newVirtualThreadPerTaskExecutor()) {
    for (var id : ids) {
        scope.submit(() -> fetchAndStore(id));
    }
}

