// Spring Boot
@RestController
@RequestMapping('/api/users')
class UserController {
  private final UserService service;
  UserController(UserService service) { this.service = service; } // constructor injection

  @PostMapping
  ResponseEntity<UserRes> create(@Valid @RequestBody CreateUserReq req) {
    return ResponseEntity.status(201).body(service.create(req));
  }
}

// Go (chi router) — dependency ผูกไว้กับ struct ของ handler
type UserHandler struct { svc *UserService }

func (h *UserHandler) Create(w http.ResponseWriter, r *http.Request) {
    var req CreateUserReq
    if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
        writeErr(w, http.StatusBadRequest, 'invalid body'); return
    }
    if err := validate.Struct(req); err != nil {
        writeErr(w, http.StatusUnprocessableEntity, err.Error()); return
    }
    res, err := h.svc.Create(r.Context(), req)
    if err != nil { writeErr(w, http.StatusInternalServerError, 'oops'); return }
    writeJSON(w, http.StatusCreated, res)
}

