// Spring Data JPA — ประกาศ interface ก็ได้ query
interface OrderRepo extends JpaRepository<Order, Long> {
  List<Order> findByUserIdAndStatus(Long userId, Status status);
}

@Transactional
public void checkout(Long orderId) {
  Order o = repo.findById(orderId).orElseThrow();
  o.setStatus(PAID);          // ไม่ต้องเรียก save() — dirty checking จัดการให้
  payment.charge(o);          // ถ้า throw RuntimeException → rollback อัตโนมัติ
}

// Go — transaction ต้องคุมเอง ชัดเจนทุกบรรทัด
func (r *Repo) Checkout(ctx context.Context, orderID int64) error {
    tx, err := r.db.BeginTx(ctx, nil)
    if err != nil { return err }
    defer tx.Rollback() // ปลอดภัย: no-op ถ้า commit ไปแล้ว

    if _, err := tx.ExecContext(ctx,
        'UPDATE orders SET status = $1 WHERE id = $2', 'PAID', orderID); err != nil {
        return fmt.Errorf('update order: %w', err)
    }
    return tx.Commit()
}

func TestDiscount(t *testing.T) {
    tests := []struct{
        name  string
        total int
        want  int
    }{
        {'ไม่ถึงเกณฑ์', 500, 0},
        {'ถึงเกณฑ์พอดี', 1000, 100},
        {'เกินเกณฑ์', 2500, 250},
    }
    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            if got := Discount(tt.total); got != tt.want {
                t.Errorf('Discount(%d) = %d, want %d', tt.total, got, tt.want)
            }
        })
    }
}

